Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='nodefensiveguards', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Guard only what the types allow; tighten a loose type instead of adding a guard', body='Before adding a null check, a fallback, a catch block or an unexpected branch, ask if the case can happen. If the types exclude it, write no guard. If it can happen only because a type is loose, tighten the type. Parse once at the real boundary into a precise type, and trust that type inside.', rationale='A guard for an impossible case shows the author did not work out what can happen, and it adds noise.', supersedes=()))